import {requestJson} from '/request-feedback.js';
const units={amavale:'Amavale',valparaiso:'Valparaíso','vale-do-carangola':'Vale do Carangola'};
export function mountAppointmentForm(studentId){
 const main=document.querySelector('main');
 main.innerHTML=`<section class="section registration-intro"><p class="eyebrow">CADASTRO APROVADO</p><h1 tabindex="-1">Solicitar atendimento</h1><p class="lead">Escolha uma vaga presencial ou online. A reserva ficará aguardando confirmação da secretaria.</p></section><section class="section registration-layout"><form id="appointment-form"><fieldset><legend>01 · Solicitante</legend><div class="form-grid"><label>ID do aluno<input name="studentId" readonly></label><label>Nome do solicitante<input name="contactName" required minlength="3" maxlength="120" autocomplete="name"></label><label>WhatsApp com DDD<input name="phone" type="tel" inputmode="tel" required maxlength="20" autocomplete="tel"></label></div></fieldset><fieldset><legend>02 · Atendimento e disponibilidade</legend><div class="form-grid"><label>Atendimento<select name="service" required><option value="">Selecione a especialidade</option><option>Psicologia</option><option>Assistência social</option></select></label><label>Como deseja solicitar?<select name="mode"><option value="slot">Escolher uma vaga publicada</option><option value="preference">Informar preferência, sem reservar vaga</option></select></label></div><div id="slot-choice"><p role="status" id="slot-status">Selecione a especialidade para consultar as vagas.</p><label>Vaga disponível<select name="slotId"><option value="">Selecione</option></select></label><p id="slot-description"></p><button type="button" id="reload-slots" class="button">Atualizar vagas</button></div><div id="preference-choice" hidden><p class="form-status">Uma preferência entra na fila da secretaria e não bloqueia horário. Se há uma vaga publicada que atende você, escolha a opção de reserva acima.</p><div class="form-grid"><label>Modalidade desejada<select name="modality"><option value="any">Presencial ou online</option><option value="in_person">Presencial</option><option value="online">Online</option></select></label><label>Núcleo desejado<select name="unit"><option value="amavale">Amavale</option><option value="valparaiso">Valparaíso</option><option value="vale-do-carangola">Vale do Carangola</option></select></label><label>Data desejada<input name="date" type="date"></label><label>Horário desejado (Brasília)<input name="time" type="time"></label></div></div></fieldset><p>A secretaria confere a identidade do solicitante. A escolha de outro núcleo para atendimento não altera a matrícula do aluno. Em atendimento online, a equipe informará o acesso à sala após a confirmação.</p><label class="consent"><input name="consent" type="checkbox" required>Estou ciente da modalidade e do local escolhidos e aguardarei a confirmação da secretaria por WhatsApp.</label><button class="button" type="submit">Solicitar vaga</button><div class="form-status" role="status" id="appointment-result" tabindex="-1" hidden></div><p><a class="text-link" href="/agendamento/">Consultar outro ID</a></p><p><a href="/portal/#schedule-area">Entrar na área protegida para acompanhar meus atendimentos</a></p></form></section>`;
 const form=main.querySelector('form'),v=form.elements,slotBox=main.querySelector('#slot-choice'),preferenceBox=main.querySelector('#preference-choice'),status=main.querySelector('#slot-status'),description=main.querySelector('#slot-description'),result=main.querySelector('#appointment-result'),submit=form.querySelector('[type=submit]'),reload=main.querySelector('#reload-slots');
 v.studentId.value=studentId.trim().toUpperCase();v.unit.value=Object.keys(units)[Number(studentId.slice(3,4))-1]||'amavale';
 const parts=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(p=>[p.type,p.value]));v.date.min=`${parts.year}-${parts.month}-${parts.day}`;
 let slots=[],requestId=crypto.randomUUID(),generation=0,sent=false,loading=false,submitting=false;
 const post=(url,data)=>requestJson(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)},url==='/api/agenda'?'protocol':undefined);
 const timeLabel=s=>new Date(s.start_at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo',dateStyle:'short',timeStyle:'short'})+' · '+(s.modality==='online'?'Online':'Presencial')+' · '+units[s.unit]+' · '+s.professional_name;
 function toggle(){const slotMode=v.mode.value==='slot';slotBox.hidden=!slotMode;preferenceBox.hidden=slotMode;v.slotId.required=slotMode;v.date.required=v.time.required=v.unit.required=!slotMode;submit.textContent=slotMode?'Solicitar vaga':'Enviar preferência sem reservar';submit.disabled=sent||loading||submitting}
 async function loadSlots(){if(submitting||sent)return;const own=++generation;slots=[];v.slotId.replaceChildren(new Option('Selecione uma vaga',''));description.textContent='';if(!v.service.value){loading=false;reload.disabled=false;toggle();status.textContent='Selecione a especialidade para consultar as vagas.';return}loading=true;toggle();reload.disabled=true;status.textContent='Consultando vagas publicadas…';try{const data=await post('/api/agenda/slots',{studentId:v.studentId.value,service:v.service.value});if(own!==generation||!form.isConnected)return;if(!Array.isArray(data.slots))throw Error('Não foi possível confirmar a lista de vagas. Atualize a consulta.');slots=data.slots;for(const s of slots)v.slotId.append(new Option(timeLabel(s),s.id));status.textContent=slots.length?slots.length+' vagas disponíveis. Horários de Brasília.':'Não há vagas publicadas para essa especialidade. Você pode informar uma preferência para a secretaria.'}catch(error){if(own===generation)status.textContent=error.message}finally{if(own===generation){loading=false;reload.disabled=false;toggle()}}}
 v.service.addEventListener('change',loadSlots);reload.addEventListener('click',loadSlots);v.mode.addEventListener('change',toggle);v.slotId.addEventListener('change',()=>{const s=slots.find(s=>s.id===v.slotId.value);description.textContent=s?(s.modality==='online'?'Online: a equipe fornecerá o link após confirmar.':'Presencial: '+(s.location||units[s.unit])):''});
 form.addEventListener('input',()=>{if(!sent&&!submitting){requestId=crypto.randomUUID();result.hidden=true;v.phone.setCustomValidity('')}});
 form.addEventListener('submit',async event=>{event.preventDefault();if(sent||loading||submitting)return;v.phone.setCustomValidity(/^\d{10,11}$/.test(v.phone.value.replace(/\D/g,''))?'':'Informe 10 ou 11 dígitos, com DDD.');if(!form.reportValidity())return;
  const payload={studentId:v.studentId.value,contactName:v.contactName.value,phone:v.phone.value,service:v.service.value,consent:v.consent.checked,requestId};
  if(v.mode.value==='slot'){const s=slots.find(s=>s.id===v.slotId.value);if(!s)return;const local=new Date(new Date(s.start_at).getTime()-3*3600000).toISOString();Object.assign(payload,{slotId:s.id,slotVersion:s.version,unit:s.unit,modality:s.modality,date:local.slice(0,10),time:local.slice(11,16)})}else Object.assign(payload,{unit:v.unit.value,modality:v.modality.value,date:v.date.value,time:v.time.value});payload.weekday=new Date(payload.date+'T12:00:00Z').getUTCDay();
  submitting=true;form.setAttribute('aria-busy','true');const controls=[...form.querySelectorAll('input,select,button')].map(e=>[e,e.disabled]);controls.forEach(([e])=>e.disabled=true);submit.textContent='Registrando na agenda…';result.hidden=true;
  try{const data=await post('/api/agenda',payload);if(data.protocol!==payload.requestId||!['pending','waiting','confirmed','cancelled','completed','absent'].includes(data.status)||data.reserved!==['pending','confirmed'].includes(data.status))throw Error('A resposta não confirmou este protocolo. Tente novamente sem alterar os dados.');sent=true;result.textContent=data.message+' Protocolo: '+data.protocol;form.querySelectorAll('input,select,button').forEach(e=>e.disabled=true);submit.textContent=({pending:'Vaga reservada — aguardando confirmação',confirmed:'Atendimento confirmado',waiting:'Preferência registrada — sem vaga reservada',cancelled:'Solicitação cancelada',completed:'Atendimento realizado',absent:'Atendimento encerrado'})[data.status]}catch(error){result.textContent=error.message+' Seus campos foram preservados. Se a vaga foi ocupada, atualize as vagas para escolher outra.';submit.disabled=false;submit.textContent=v.mode.value==='slot'?'Solicitar vaga':'Enviar preferência sem reservar'}finally{submitting=false;form.removeAttribute('aria-busy');if(!sent)controls.forEach(([e,disabled])=>e.disabled=disabled);result.hidden=false;result.focus()}
 });toggle();main.querySelector('h1').focus();
}
